53:             'text-font': findFonts(map),
54:             'text-size': 12,
55:             'symbol-sort-key': ['get', 'id'],
56:           }
57:         : {
58:             'icon-image': '{image}',
59:             'icon-size': iconScale,
60:             'icon-allow-overlap': true,
61:             'symbol-sort-key': ['get', 'id'],
62:           },
63:       ...(showTitles ? { paint: { 'text-halo-color': 'white', 'text-halo-width': 1 } } : {}),
64:       ...(onClick
65:         ? { on: { mouseenter: onMouseEnter, mouseleave: onMouseLeave, click: onMarkerClick } }
66:         : {}),
67:     },
68:   ];
69: 
70:   if (direction) {
71:     layers.push({
72:       key: 'direction',
73:       type: 'symbol',
74:       filter: ['all', ['!has', 'point_count'], ['==', 'direction', true]],
75:       layout: {
