80:     'activeMapStyles',
81:     'locationIqStreets,locationIqDark,openFreeMap',
82:   );
83:   const [selectedStyleId, setSelectedStyleId] = usePersistedState(
84:     'selectedMapStyle',
85:     usePreference('map', 'locationIqStreets'),
86:   );
87:   const maxZoom = useAttributePreference('web.maxZoom');
88: 
89:   const styles = useMemo(() => {
90:     const filtered = mapStyles.filter((s) => s.available && activeMapStyles.includes(s.id));
91:     return filtered.length ? filtered : mapStyles.filter((s) => s.id === 'osm');
92:   }, [mapStyles, activeMapStyles]);
93: 
94:   useAsyncTask(async () => {
95:     if (theme.direction === 'rtl') {
96:       maplibregl.setRTLTextPlugin('/mapbox-gl-rtl-text.js');
97:     }
98:   }, [theme.direction]);
