15: export const useAsyncTask = (effect, deps) => {
16:   const dispatch = useDispatch();
17:   useEffect(() => {
18:     const controller = new AbortController();
19:     let cleanup;
20:     effect({ signal: controller.signal })
21:       .then((result) => {
22:         cleanup = result;
23:       })
24:       .catch((error) => {
25:         if (error.name !== 'AbortError') {
26:           dispatch(errorsActions.push(error.message));
27:         }
28:       });
29:     return () => {
30:       controller.abort();
31:       cleanup?.();
32:     };
33:     // eslint-disable-next-line @eslint-react/exhaustive-deps
34:   }, [...deps, dispatch]);
35: };
